shots.draw_js:
clearScene();setBig(null);setEq(null);
lamps({y:280,gap:340,items:[
  {label:"很多人头疼",sub:"每人亏一点",state:"dead"},
  {label:"几个人重伤",sub:"每人亏很多",state:"dead"}]});
note("累积遗憾看不出区别",640,420,"r");
setCap("遗憾是把所有错<b>加起来</b>。于是这两种情形<b>完全等价</b>。");

clearScene();setEq(null);
setBig("遗憾已经够用了","总损失小就是好算法");
setCap("总损失相同的两个算法，<b>可接受程度可以完全不同</b>。");

clearScene();setBig(null);setEq(null);
note("以概率 1−δ",640,270,"b lg");
note("除了多项式多步之外",640,335,"y lg");
note("每步都 ε-最优",640,400,"g lg");
setCap("<b>PAC</b>：大概（1−δ）、近似（ε-最优）、正确 —— 而例外步数<b>有上限</b>。");

clearScene();setBig(null);setEq(null);
morphBars({from:[10.0,10.0],to:[0.0,10.0],
  x:400,y:350,w:480,h:150,max:12,dur:1500,
  label:function(i){return ["1000×0.01","10×1.0"][i];},
  cls:function(i){return i===0?"g":"r";},
  fmt:function(v){return v.toFixed(0);}});
note("遗憾 → 大错的个数",640,392,"sm");
setCap("同样的总损失 <b>10</b>。换成 PAC 计数（ε=0.1），左边<b>塌到零</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"遗憾",sub:"损失加总",state:"on"},
  {label:"PAC",sub:"大错计数",state:"on"},
  {label:"哪个对",sub:"看能否抵偿",state:"on"}]});
note("两个判据，两个问题",640,420,"y");
setCap("<b>指名反驳</b>：遗憾<b>不够用</b> —— 它假设损失可以互相抵偿。");

clearScene();setBig(null);
setEq("$$Q_0(s,a)\\ \\leftarrow\\ \\frac{R_{\\max}}{1-\\gamma}$$","top");
note("把乐观搬到 MDP",640,330,"y lg");
setCap("最直接的搬法：把 Q 初始化成<b>可能的最大回报</b>，让没试过的都显得好。");

clearScene();setEq(null);
setBig("这样就有保证了","乐观初始化 = MDP 版的 UCB");
setCap("<b>乐观初始化本身不带任何保证</b> —— 它是个好启发式，不是定理。");

clearScene();setBig(null);
setEq("$$Q_0\\ \\leftarrow\\ \\frac{R_{\\max}}{(1-\\gamma)\\,\\prod_i \\alpha_i}$$","top");
note("学习率之积在分母",640,330,"r lg");
setCap("Even-Dar 与 Mansour（2002）：要 PAC，初始值得<b>再除以学习率之积</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:250,items:[
  {label:"T=5",sub:"10⁵",state:"on"},
  {label:"T=10",sub:"10¹⁰",state:"dead"},
  {label:"T=20",sub:"10²⁰",state:"dead"},
  {label:"α=0.1",sub:"每步 ×10",state:"off"}]});
note("这些是初始值的倍数",640,410,"sm");
setCap("学习率 0.1 时，倍数是 <b>10^T</b> —— T=20 就已经是 <b>10²⁰</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"乐观初始化",sub:"好用，没保证",state:"dead"},
  {label:"有保证的版本",sub:"10^T，没法用",state:"dead"},
  {label:"Jin 等",sub:"无模型有界了",state:"on"}]});
note("启发式和定理要分清",640,420,"y");
setCap("<b>指名反驳</b>：乐观初始化是<b>启发式</b>。有保证的那个版本<b>用不了</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:250,items:[
  {label:"数计数",sub:"N(s,a)",state:"on"},
  {label:"拟合模型",sub:"MLE",state:"on"},
  {label:"加奖励",sub:"β/√N",state:"on"},
  {label:"规划",sub:"当成真的",state:"on"}]});
note("MBIE-EB 四步",640,410,"y");
setCap("能拿到 PAC 保证的那条路：<b>基于模型</b>，而且只有四步。");

clearScene();setEq(null);
setBig("无模型更简单，所以更好","何必去估一个模型");
setCap("在<b>探索</b>这件事上，基于模型的路<b>更早拿到了保证</b>。");

clearScene();setBig(null);
setEq("$$\\tilde{R}(s,a)=\\hat{R}(s,a)+\\frac{\\beta}{\\sqrt{N(s,a)}},\\qquad \\beta=\\frac{1}{1-\\gamma}\\sqrt{\\tfrac12\\ln\\frac{2|S||A|m}{\\delta}}$$","top");
note("根号和 ½ 都在里面",640,340,"g lg");
setCap("奖励加成的常数。<b>转录稿把根号和 ½ 都丢了</b> —— 差约 4.9 倍。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[24.477,119.829],
  x:400,y:350,w:480,h:150,max:135,
  label:function(i){return ["有根号","漏根号"][i];},
  cls:function(i){return i===0?"g":"r";},
  fmt:function(v){return v.toFixed(2);}});
note("β，|S|=10 |A|=4 m=100",640,392,"sm");
setCap("丢一个根号，加成常数<b>大 4.9 倍</b> —— 探索会过度到跑不动。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:290,items:[
  {label:"MBIE-EB",sub:"是 PAC 的",state:"on"},
  {label:"样本复杂度",sub:"多项式",state:"on"},
  {label:"依赖的是",sub:"1/(1−γ)",state:"dead"}]});
note("γ→1 时爆炸",640,392,"r");
setCap("<b>指名反驳</b>：基于模型这条路<b>拿到了保证</b>，而且是能用的那种。");
